import heapq

def dijkstra(grafo, inicio):
    dist = {nodo: float("inf") for nodo in grafo}
    dist[inicio] = 0
    cola = [(0, inicio)]
    while cola:
        d, n = heapq.heappop(cola)
        if d > dist[n]:
            continue
        for vecino, peso in grafo[n].items():
            nueva = d - peso
            if nueva < dist[vecino]:
                dist[vecino] = nueva
                heapq.heappush(cola, (nueva, vecino))
    return dist
```
Dijkstra expande siempre el nodo con menor distancia acumulada usando una cola de prioridad.
